<?php
$profileUser=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!cds_account_csrf_valid((string)($_POST['csrf']??''))) flash('Phiên làm việc không hợp lệ, vui lòng thử lại.','danger');
    elseif(($_POST['profile_action']??'')==='save_profile'){$result=cds_account_update_profile((string)($profileUser['id']??''),$_POST);flash($result['message'],!empty($result['ok'])?'success':'danger');}
    elseif(($_POST['profile_action']??'')==='upload_photo'){$result=cds_account_upload_teacher_photo((string)($profileUser['id']??''),(array)($_FILES['teacher_photo']??[]));flash($result['message'],!empty($result['ok'])?'success':'danger');}
    elseif(($_POST['profile_action']??'')==='change_password'){$result=cds_account_change_password((string)($profileUser['id']??''),(string)($_POST['current_password']??''),(string)($_POST['new_password']??''),(string)($_POST['confirm_password']??''));flash($result['message'],!empty($result['ok'])?'success':'danger');}
    header('Location: '.BASE_URL.'admin.php?view=profile');exit;
}
$profileUser=find_user_by_id((string)($profileUser['id']??''))?:$profileUser;$profile=cds_account_profile($profileUser);$profileTeacher=cds_account_teacher_for_user($profileUser);$profileHasPhoto=$profileTeacher?staff_card_has_photo((string)$profileTeacher['id']):false;
