<script>const input=document.getElementById('teacherPhoto');if(input)input.addEventListener('change',()=>{const file=input.files&&input.files[0],img=document.getElementById('photoPreview'),placeholder=document.getElementById('photoPlaceholder');if(!file)return;img.src=URL.createObjectURL(file);img.classList.remove('d-none');if(placeholder)placeholder.classList.add('d-none')});</script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
